-- Migration 20261025050000_memory: generated by drizzle-kit (tables, keys, checks, indexes), RLS, scope policies, the clerk policy function and view hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #72)
-- Lawyer memory (#72, ADR 0037): memory_item, memory_proposal, memory_embedding, memory_usage and memory_pause are tenant tables under FORCE RLS (ws_isolation). On top of that:
--   * memory_item_owner_scope (RESTRICTIVE): a user-scope item is visible to its owner only, unless an owner shared it with the chamber (M4 notes only, CHECK memory_item_shared_chk). No acting user (a job such as erasure) is not restricted.
--   * memory_item_matter_scope / memory_embedding_matter_scope (RESTRICTIVE): when the transaction pins app.matter_id, a matter-scoped row is visible only for that matter.
--   * memory_clerk_readable(layer, strategy): the clerk policy function. Clerks read M1, M2, M6 and M7 values that are not strategy-typed, never M3 or M4.
--   * memory_item_clerk_v: the clerk column-scoped view (no source_ref, anchor_id, confidence, proposal_id, deleted_at) over the readable rows only; the clerk role has no privilege on memory_item, memory_proposal or memory_embedding.
--   * owner_definer_read + app_memory_purge_targets() / app_memory_review_targets(): ids-only target lists for the memory.purge and memory.review-prepare schedules.
-- New tables, functions and a view only: nothing existing is altered or dropped.
CREATE TABLE "memory_embedding" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"item_id" uuid NOT NULL,
	"matter_id" uuid,
	"content_ref" text NOT NULL,
	"embedding" vector(1024) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL
);
--> statement-breakpoint
CREATE TABLE "memory_item" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"layer" text NOT NULL,
	"key" text NOT NULL,
	"scope" text NOT NULL,
	"matter_id" uuid,
	"person_id" uuid,
	"owner_user_id" uuid NOT NULL,
	"value_ciphertext" text,
	"source_type" text NOT NULL,
	"source_ref" text,
	"anchor_id" uuid,
	"confidence" numeric(4, 3),
	"confirmation_state" text NOT NULL,
	"status" text DEFAULT 'active' NOT NULL,
	"strategy" boolean DEFAULT false NOT NULL,
	"shared_with_chamber" boolean DEFAULT false NOT NULL,
	"proposal_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "memory_item_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "memory_item_layer_chk" CHECK (layer in ('M1', 'M2', 'M3', 'M4', 'M6', 'M7')),
	CONSTRAINT "memory_item_scope_chk" CHECK (scope in ('user', 'workspace', 'matter')),
	CONSTRAINT "memory_item_status_chk" CHECK (status in ('active', 'paused', 'deleted')),
	CONSTRAINT "memory_item_confirmation_chk" CHECK (confirmation_state in ('confirmed', 'corrected')),
	CONSTRAINT "memory_item_key_layer_chk" CHECK (key like layer || '.%'),
	CONSTRAINT "memory_item_matter_scope_chk" CHECK ((scope = 'matter') = (matter_id is not null)),
	CONSTRAINT "memory_item_layer_scope_chk" CHECK ((layer = 'M3') = (scope = 'matter')),
	CONSTRAINT "memory_item_person_chk" CHECK ((layer = 'M6') = (person_id is not null)),
	CONSTRAINT "memory_item_shared_chk" CHECK (not shared_with_chamber or layer = 'M4'),
	CONSTRAINT "memory_item_value_chk" CHECK ((status = 'deleted') = (value_ciphertext is null) and (status = 'deleted') = (deleted_at is not null))
);
